class Solution {
public:
    vector<int> longestObstacleCourseAtEachPosition(vector<int>& obstacles) {
        int n = obstacles.size();
        vector<int> ans(n);
        vector<int> tails;
        for (int i = 0; i < n; i++) {
            int h = obstacles[i];
            int j = upper_bound(tails.begin(), tails.end(), h) - tails.begin();
            ans[i] = j + 1;
            if (j == (int)tails.size()) {
                tails.push_back(h);
            } else {
                tails[j] = h;
            }
        }
        return ans;
    }
};
